import { BytesReader } from "../../io/BytesReader.js";
import { RawRaster } from "../../raster/RawRaster.js";
import { GaluchatImageDataChunk01Reader } from "../../chunk/gi01/GaluchatImageDataChunk01Reader.js";
import { WGSMapSetHeader3 } from "./WGSMapSetHeader3.js";

export class GaluchatWGSMapSet3Reader {
  constructor(header, bytes, chunkOffset) {
    this.header = header;
    this.bytes = bytes;
    this.chunkOffset = chunkOffset;
    this._area = null;
  }

  static fromUint8Array(bytes) {
    return GaluchatWGSMapSet3Reader.unpack(bytes);
  }

  static unpack(bytes) {
    const reader = new BytesReader(bytes);
    const header = WGSMapSetHeader3.unpack(reader);
    if (hasLayoutChunk(bytes, reader.pos)) {
      skipChunk(reader);
    }
    return new GaluchatWGSMapSet3Reader(header, bytes, reader.pos);
  }

  get unitInvX() {
    return this.header.unitInvX;
  }

  get unitInvY() {
    return this.header.unitInvY;
  }

  get numOfMaps() {
    return this.header.numOfMaps;
  }

  getChunkReader(index) {
    if (index < 0 || index >= this.header.numOfMaps) {
      throw new RangeError("WGSMapSet/3 map index out of range");
    }
    let offset = this.chunkOffset;
    let chunk = null;
    for (let i = 0; i <= index; i++) {
      chunk = new GaluchatImageDataChunk01Reader(this.bytes, offset);
      offset += chunk.chunkSize;
    }
    return chunk;
  }

  get area() {
    if (this._area !== null) {
      return this._area;
    }
    const origins = this.header.getMapSet();
    let offset = this.chunkOffset;
    let left = null;
    let top = null;
    let right = null;
    let bottom = null;
    for (const origin of origins) {
      const chunk = new GaluchatImageDataChunk01Reader(this.bytes, offset);
      offset += chunk.chunkSize;
      left = left === null ? origin.west : Math.min(left, origin.west);
      top = top === null ? origin.south : Math.min(top, origin.south);
      right = right === null ? origin.west + chunk.width : Math.max(right, origin.west + chunk.width);
      bottom = bottom === null ? origin.south + chunk.height : Math.max(bottom, origin.south + chunk.height);
    }
    this._area = { x: left, y: top, width: right - left, height: bottom - top };
    return this._area;
  }

  get areaOfWgs() {
    const area = this.area;
    return {
      x: area.x / this.header.unitInvX,
      y: area.y / this.header.unitInvY,
      width: area.width / this.header.unitInvX,
      height: area.height / this.header.unitInvY,
    };
  }

  readWgsPoint(ix, iy) {
    let offset = this.chunkOffset;
    let zeroHit = null;
    for (const origin of this.header.getMapSet()) {
      const chunk = new GaluchatImageDataChunk01Reader(this.bytes, offset);
      offset += chunk.chunkSize;
      if (ix < origin.west || iy < origin.south
        || ix >= origin.west + chunk.width
        || iy >= origin.south + chunk.height) {
        continue;
      }
      const value = chunk.readPoint(ix - origin.west, iy - origin.south);
      if (value !== 0) {
        return value;
      }
      zeroHit = 0;
    }
    return zeroHit;
  }

  readWgsPointf(lon, lat) {
    return this.readWgsPoint(
      Math.round(lon * this.header.unitInvX),
      Math.round(lat * this.header.unitInvY),
    );
  }

  readRect(x, y, width, height) {
    const area = this.area;
    return this.readWgsRect({ x: area.x + x, y: area.y + y, width, height });
  }

  readWgsRect(target) {
    const dest = RawRaster.createRaster(target.width, target.height);
    let offset = this.chunkOffset;
    for (const origin of this.header.getMapSet()) {
      const chunk = new GaluchatImageDataChunk01Reader(this.bytes, offset);
      offset += chunk.chunkSize;
      const chunkArea = { x: origin.west, y: origin.south, width: chunk.width, height: chunk.height };
      const crossed = crossRect(chunkArea, target);
      if (crossed === null) {
        continue;
      }
      const temp = RawRaster.createRaster(crossed.width, crossed.height);
      chunk.readRect(crossed.x - origin.west, crossed.y - origin.south, temp);
      for (let y = 0; y < crossed.height; y++) {
        for (let x = 0; x < crossed.width; x++) {
          const value = temp.get(x, y);
          if (value !== 0) {
            dest.set(crossed.x - target.x + x, crossed.y - target.y + y, value);
          }
        }
      }
    }
    return dest;
  }

  readWgsRectf(rect) {
    return this.readWgsRect({
      x: Math.round(rect.x * this.header.unitInvX),
      y: Math.round(rect.y * this.header.unitInvY),
      width: Math.round(rect.width * this.header.unitInvX),
      height: Math.round(rect.height * this.header.unitInvY),
    });
  }

  toRaster() {
    return this.readWgsRect(this.area);
  }
}

function hasLayoutChunk(bytes, offset) {
  return bytes.length >= offset + 4
    && bytes[offset] === 0x4c
    && bytes[offset + 1] === 0x41
    && bytes[offset + 2] === 0x59
    && bytes[offset + 3] === 0x4f;
}

function skipChunk(reader) {
  reader.skipInByte(4);
  const size = reader.readMbUInt();
  reader.skipInByte(size);
}

function crossRect(a, b) {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  return x < right && y < bottom ? { x, y, width: right - x, height: bottom - y } : null;
}
