import { RawRaster } from "../../raster/RawRaster.js";
import { FastMapImageRenderer } from "../../api/maprender/index.js";
import {
  GaluchatLocalMapSource,
  createMapImageRenderOptions,
} from "./GaluchatLocalMapSource.js";

export class MultiZoomMapSource extends GaluchatLocalMapSource {
  constructor({
    displayReaders,
    resolverReader,
    levels,
    padding = 128,
    levelIndex = 0,
    renderer = new FastMapImageRenderer(),
    ...options
  } = {}) {
    if (displayReaders == null || typeof displayReaders !== "object") {
      throw new TypeError("displayReaders is required");
    }
    if (!Array.isArray(levels) || levels.length === 0) {
      throw new TypeError("levels must be a non-empty array");
    }
    super({ ...options, mapsetReader: resolverReader, renderer });
    this.displayReaders = displayReaders;
    this.levels = levels.map(normalizeLevel);
    this.padding = padding;
    this.levelIndex = clampLevelIndex(levelIndex, this.levels);
    this.offscreen = null;
  }

  get currentLevel() {
    return this.levels[this.levelIndex];
  }

  get currentReader() {
    return this.displayReaders[this.currentLevel.mapset];
  }

  get currentPixelScale() {
    return this.resolveZoomPixelScale(this.levelIndex);
  }

  getZoomLevelIndex() {
    return this.levelIndex;
  }

  getZoomLevelCount() {
    return this.levels.length;
  }

  getZoomLevel(index = this.levelIndex) {
    return this.levels[clampLevelIndex(index, this.levels)];
  }

  setZoomLevelIndex(index) {
    this.levelIndex = clampLevelIndex(index, this.levels);
  }

  setLevelIndex(index) {
    this.setZoomLevelIndex(index);
  }

  resolveZoomPixelScale(index = this.levelIndex) {
    const level = this.getZoomLevel(index);
    return this.resolvePixelScale(level);
  }

  resolvePixelScale(level) {
    const reader = this.displayReaders[level.mapset];
    if (reader == null) {
      throw new Error(`display reader is not found: ${level.mapset}`);
    }
    const scaleX = this.mapsetReader.unitInvX / reader.unitInvX;
    const scaleY = this.mapsetReader.unitInvY / reader.unitInvY;
    if (scaleX !== scaleY) {
      throw new Error("multi zoom requires equal X/Y mapset resolution ratios");
    }
    return level.scale * scaleX;
  }

  snapCenter(center, index = this.levelIndex) {
    const unitInv = this.mapsetReader.unitInvX / this.resolveZoomPixelScale(index);
    return snapLonLat(center, unitInv);
  }

  render(center, width, height, options = {}) {
    const level = this.currentLevel;
    const reader = this.currentReader;
    const pixelScale = this.currentPixelScale;
    const effectiveUnitInv = this.mapsetReader.unitInvX / pixelScale;
    const snappedCenter = snapLonLat(center, effectiveUnitInv);
    const viewportSourceRect = resolveScaledRect(reader, snappedCenter, width, height, level.scale);
    const resolverRect = resolveScaledRect(this.mapsetReader, snappedCenter, width, height, pixelScale);
    const cacheResult = this.ensureOffscreen(viewportSourceRect, level, reader);
    const displayRaster = copyRasterRect(this.offscreen.raster, this.offscreen.rect, cacheResult.viewportRect);
    const image = this.renderer.renderRaster(
      displayRaster,
      createMapImageRenderOptions(options.style, options.selectedCode ?? null),
    );
    return {
      image,
      rect: resolverRect,
      pixelScale,
      center: snappedCenter,
      debug: {
        ...cacheResult,
        summary: [
          `level=${level.id}`,
          `effective=${effectiveUnitInv}`,
          cacheResult.hit ? "offscreen=hit" : "offscreen=miss",
          `mode=${cacheResult.mode}`,
          `strips=${cacheResult.stripCount}`,
          `read=${cacheResult.readCount}`,
          `readMs=${cacheResult.readMs.toFixed(1)}ms`,
          `workMs=${cacheResult.workMs.toFixed(1)}ms`,
          `cache=${this.offscreen.raster.width}x${this.offscreen.raster.height}`,
        ].join(" "),
      },
    };
  }

  ensureOffscreen(viewportSourceRect, level, reader) {
    const phase = sourcePhase(viewportSourceRect, level.scale);
    const viewportRect = sourceRectToDisplayRect(viewportSourceRect, level.scale, phase);
    if (
      this.offscreen !== null
      && this.offscreen.levelId === level.id
      && this.offscreen.phase.x === phase.x
      && this.offscreen.phase.y === phase.y
      && containsRect(this.offscreen.rect, viewportRect)
    ) {
      return { hit: true, mode: "hit", readCount: 0, stripCount: 0, readMs: 0, workMs: 0, viewportRect };
    }
    const nextRect = expandRect(viewportRect, this.padding);
    const nextRaster = RawRaster.createRaster(nextRect.width, nextRect.height);

    if (
      this.offscreen === null
      || this.offscreen.levelId !== level.id
      || this.offscreen.phase.x !== phase.x
      || this.offscreen.phase.y !== phase.y
    ) {
      const readResult = readDisplayRectInto(reader, nextRect, level.scale, phase, nextRaster, 0, 0);
      this.offscreen = { rect: nextRect, raster: nextRaster, levelId: level.id, phase };
      return { hit: false, mode: "full", readCount: 1, stripCount: 0, ...readResult, viewportRect };
    }

    const crossed = crossRect(this.offscreen.rect, nextRect);
    if (crossed === null) {
      const readResult = readDisplayRectInto(reader, nextRect, level.scale, phase, nextRaster, 0, 0);
      this.offscreen = { rect: nextRect, raster: nextRaster, levelId: level.id, phase };
      return { hit: false, mode: "full", readCount: 1, stripCount: 0, ...readResult, viewportRect };
    }

    copyRasterArea(
      this.offscreen.raster,
      crossed.x - this.offscreen.rect.x,
      crossed.y - this.offscreen.rect.y,
      nextRaster,
      crossed.x - nextRect.x,
      crossed.y - nextRect.y,
      crossed.width,
      crossed.height,
    );

    const stripResult = readMissingStrips(
      reader,
      subtractRect(nextRect, crossed),
      nextRaster,
      nextRect,
      level.scale,
      phase,
    );
    this.offscreen = { rect: nextRect, raster: nextRaster, levelId: level.id, phase };
    return { hit: false, mode: "strip", ...stripResult, viewportRect };
  }
}

function normalizeLevel(level) {
  if (level == null || typeof level !== "object") {
    throw new TypeError("zoom level must be an object");
  }
  if (level.mapset == null) {
    throw new TypeError("zoom level mapset is required");
  }
  const scale = level.scale ?? 1;
  if (!Number.isInteger(scale) || scale < 1) {
    throw new RangeError("zoom level scale must be an integer greater than or equal to 1");
  }
  return {
    id: level.id ?? `${level.mapset}/${scale}`,
    mapset: level.mapset,
    scale,
  };
}

function readMissingStrips(reader, strips, dest, destRect, scale, phase) {
  let readCount = 0;
  let readMs = 0;
  let workMs = 0;
  for (const strip of strips) {
    const readResult = readDisplayRectInto(
      reader,
      strip,
      scale,
      phase,
      dest,
      strip.x - destRect.x,
      strip.y - destRect.y,
    );
    readMs += readResult.readMs;
    workMs += readResult.workMs;
    readCount += 1;
  }
  return { readCount, stripCount: strips.length, readMs, workMs };
}

function resolveScaledRect(reader, center, width, height, scale) {
  const point = {
    x: Math.round(center.lon * reader.unitInvX),
    y: Math.round(center.lat * reader.unitInvY),
  };
  const scaledWidth = width * scale;
  const scaledHeight = height * scale;
  return {
    x: point.x - Math.floor(scaledWidth / 2),
    y: point.y - Math.floor(scaledHeight / 2),
    width: scaledWidth,
    height: scaledHeight,
  };
}

function sourcePhase(sourceRect, scale) {
  return {
    x: positiveModulo(sourceRect.x, scale),
    y: positiveModulo(sourceRect.y, scale),
  };
}

function sourceRectToDisplayRect(sourceRect, scale, phase) {
  return {
    x: (sourceRect.x - phase.x) / scale,
    y: (sourceRect.y - phase.y) / scale,
    width: sourceRect.width / scale,
    height: sourceRect.height / scale,
  };
}

function displayRectToSourceRect(displayRect, scale, phase) {
  return {
    x: phase.x + displayRect.x * scale,
    y: phase.y + displayRect.y * scale,
    width: displayRect.width * scale,
    height: displayRect.height * scale,
  };
}

function readDisplayRectInto(reader, displayRect, scale, phase, dest, destX, destY) {
  const sourceRect = displayRectToSourceRect(displayRect, scale, phase);
  const start = performance.now();
  const sourceRaster = reader.readWgsRect(sourceRect);
  const afterRead = performance.now();
  if (scale === 1) {
    copyRasterArea(sourceRaster, 0, 0, dest, destX, destY, displayRect.width, displayRect.height);
  } else {
    shrinkRasterInto(sourceRaster, displayRect.width, displayRect.height, scale, dest, destX, destY);
  }
  const end = performance.now();
  return {
    readMs: afterRead - start,
    workMs: end - afterRead,
  };
}

function shrinkRasterInto(sourceRaster, width, height, scale, dest, destX, destY) {
  const sourceData = sourceRaster.data;
  const destData = dest.data;
  const scratch = {
    values: new Uint32Array(scale * scale),
    counts: new Uint8Array(scale * scale),
    order: new Uint32Array(scale * scale),
  };
  for (let y = 0; y < height; y += 1) {
    const sourceY = y * scale;
    const destRowOffset = (destY + y) * dest.width + destX;
    for (let x = 0; x < width; x += 1) {
      destData[destRowOffset + x] = majorityBlockFast(
        sourceData,
        sourceRaster.width,
        x * scale,
        sourceY,
        scale,
        scratch,
      );
    }
  }
}

function majorityBlockFast(sourceData, sourceWidth, startX, startY, scale, scratch) {
  const values = scratch.values;
  const counts = scratch.counts;
  const order = scratch.order;
  let uniqueCount = 0;
  let orderCount = 0;
  let maxCount = 0;
  for (let y = scale - 1; y >= 0; y -= 1) {
    const rowOffset = (startY + y) * sourceWidth + startX;
    for (let x = 0; x < scale; x += 1) {
      const value = sourceData[rowOffset + x];
      order[orderCount] = value;
      orderCount += 1;
      let index = -1;
      for (let i = 0; i < uniqueCount; i += 1) {
        if (values[i] === value) {
          index = i;
          break;
        }
      }
      if (index < 0) {
        index = uniqueCount;
        values[index] = value;
        counts[index] = 0;
        uniqueCount += 1;
      }
      counts[index] += 1;
      if (counts[index] > maxCount) {
        maxCount = counts[index];
      }
    }
  }
  let candidateCount = 0;
  let firstCandidate = 0;
  let hasNonZeroCandidate = false;
  for (let i = 0; i < uniqueCount; i += 1) {
    if (counts[i] !== maxCount) {
      continue;
    }
    candidateCount += 1;
    firstCandidate = values[i];
    if (values[i] !== 0) {
      hasNonZeroCandidate = true;
    }
  }
  if (candidateCount === 1) {
    return firstCandidate;
  }
  for (let i = 0; i < orderCount; i += 1) {
    const value = order[i];
    if (hasNonZeroCandidate && value === 0) {
      continue;
    }
    for (let uniqueIndex = 0; uniqueIndex < uniqueCount; uniqueIndex += 1) {
      if (values[uniqueIndex] === value && counts[uniqueIndex] === maxCount) {
        return value;
      }
    }
  }
  return 0;
}

function copyRasterRect(sourceRaster, sourceRect, targetRect) {
  const dest = RawRaster.createRaster(targetRect.width, targetRect.height);
  copyRasterArea(
    sourceRaster,
    targetRect.x - sourceRect.x,
    targetRect.y - sourceRect.y,
    dest,
    0,
    0,
    targetRect.width,
    targetRect.height,
  );
  return dest;
}

function copyRasterArea(sourceRaster, sourceX, sourceY, dest, destX, destY, width, height) {
  if (sourceRaster.data instanceof Uint32Array && dest.data instanceof Uint32Array) {
    for (let y = 0; y < height; y += 1) {
      const sourceOffset = (sourceY + y) * sourceRaster.width + sourceX;
      const destOffset = (destY + y) * dest.width + destX;
      dest.data.set(sourceRaster.data.subarray(sourceOffset, sourceOffset + width), destOffset);
    }
    return;
  }
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      dest.set(destX + x, destY + y, sourceRaster.get(sourceX + x, sourceY + y));
    }
  }
}

function expandRect(rect, padding) {
  return {
    x: rect.x - padding,
    y: rect.y - padding,
    width: rect.width + padding * 2,
    height: rect.height + padding * 2,
  };
}

function containsRect(container, item) {
  return container.x <= item.x
    && container.y <= item.y
    && container.x + container.width >= item.x + item.width
    && container.y + container.height >= item.y + item.height;
}

function crossRect(a, b) {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const top = Math.min(a.y + a.height, b.y + b.height);
  return x < right && y < top ? { x, y, width: right - x, height: top - y } : null;
}

function subtractRect(rect, inner) {
  const result = [];
  const rectRight = rect.x + rect.width;
  const rectTop = rect.y + rect.height;
  const innerRight = inner.x + inner.width;
  const innerTop = inner.y + inner.height;

  pushRect(result, rect.x, rect.y, inner.x - rect.x, rect.height);
  pushRect(result, innerRight, rect.y, rectRight - innerRight, rect.height);
  pushRect(result, inner.x, rect.y, inner.width, inner.y - rect.y);
  pushRect(result, inner.x, innerTop, inner.width, rectTop - innerTop);
  return result;
}

function pushRect(result, x, y, width, height) {
  if (width > 0 && height > 0) {
    result.push({ x, y, width, height });
  }
}

function clampLevelIndex(index, levels) {
  return Math.min(Math.max(Math.floor(index), 0), levels.length - 1);
}

function snapLonLat(center, unitInv) {
  return {
    lon: Math.round(center.lon * unitInv) / unitInv,
    lat: Math.round(center.lat * unitInv) / unitInv,
  };
}

function positiveModulo(value, divisor) {
  return ((value % divisor) + divisor) % divisor;
}
