import { BytesReader } from "../io/BytesReader.js";

const GISWORDBOOK_VERSION = "GisWordBook/0";
const GISWORDBOOK_HEADER_CHUNK = "GW00";
const TOKEN_MAP_CHUNK = "TM00";
const TEXT_TABLE_CHUNK = "TT00";
const HIERARCHICAL_INDEX_CHUNK = "TI00";
const PALETTE_SIZE = 15;

const textDecoder = new TextDecoder("utf-8");

export class GaluchatGisWordBookReader {
  constructor(header, tokenMap, textTable, index) {
    this.header = header;
    this.tokenMap = tokenMap;
    this.textTable = textTable;
    this.index = index;
    this._codeBuffer = new Array(index.maxDepth).fill(0);
  }

  static fromUint8Array(bytes, options = {}) {
    return GaluchatGisWordBookReader.unpack(bytes, options);
  }

  static unpack(bytes, options = {}) {
    if (!(bytes instanceof Uint8Array)) {
      throw new TypeError("GaluchatGisWordBookReader requires Uint8Array");
    }

    const reader = new BytesReader(bytes);
    const headerChunk = readMappedChunk(reader, bytes.length);
    if (headerChunk.name !== GISWORDBOOK_HEADER_CHUNK) {
      throw new Error("GisWordBook must start with GW00");
    }

    const tokenChunk = readMappedChunk(reader, bytes.length);
    if (tokenChunk.name !== TOKEN_MAP_CHUNK) {
      throw new Error("GisWordBook must contain TM00 after GW00");
    }

    const textChunk = readMappedChunk(reader, bytes.length);
    if (textChunk.name !== TEXT_TABLE_CHUNK) {
      throw new Error("GisWordBook must contain TT00 after TM00");
    }

    const indexChunk = readMappedChunk(reader, bytes.length);
    if (indexChunk.name !== HIERARCHICAL_INDEX_CHUNK) {
      throw new Error("GisWordBook must contain TI00 after TT00");
    }
    if (reader.pos !== bytes.length) {
      throw new Error("GisWordBook has trailing bytes");
    }

    const header = parseGisWordBookHeader(bytes, headerChunk.dataStart, headerChunk.size);
    const tokenMap = TokenMapChunkReader.unpack(
      bytes,
      tokenChunk.dataStart,
      tokenChunk.size,
      options.tokenCacheSize ?? 64,
    );
    const textTable = TextTableChunkReader.unpack(bytes, textChunk.dataStart, textChunk.size);
    const index = HierarchicalIndexChunkReader.unpack(bytes, indexChunk.dataStart, indexChunk.size);

    if (textTable.tokenBits < requiredBits(tokenMap.tokenCount)) {
      throw new Error("TT00 token_bits is smaller than TM00 token table requires");
    }
    if (index.codeBits < requiredBits(textTable.recordCount)) {
      throw new Error("TI00 code_bits is smaller than TT00 text table requires");
    }

    return new GaluchatGisWordBookReader(header, tokenMap, textTable, index);
  }

  get recordCount() {
    return this.index.recordCount;
  }

  get depth() {
    return this.index.maxDepth;
  }

  get componentCount() {
    return this.textTable.recordCount;
  }

  readCodeSet(index, out = null) {
    return this.index.readCodeSet(index, out);
  }

  readComponentBytes(code) {
    if (!Number.isInteger(code) || code < 0 || code >= this.textTable.recordCount) {
      throw new RangeError("WordBook component code out of range");
    }
    let recordBase = 0;
    for (const page of this.textTable.pages) {
      if (code < recordBase + page.pageRecordCount) {
        return decodeMappedPageRecordWithTokenGetter(
          this.tokenMap.data,
          page,
          code - recordBase,
          this.textTable.tokenBits,
          (tokenId) => this.tokenMap.get(tokenId),
        );
      }
      recordBase += page.pageRecordCount;
    }
    throw new RangeError("WordBook component code out of range");
  }

  readComponent(code) {
    return textDecoder.decode(this.readComponentBytes(code));
  }

  readStringSet(index, out = null) {
    const codes = this.readCodeSet(index, this._codeBuffer);
    const result = out ?? [];
    result.length = 0;
    for (const code of codes) {
      result.push(this.readComponent(code));
    }
    return result;
  }

  readStringSetByCode(code, out = null) {
    if (code === null || code <= 0) {
      return null;
    }
    return this.readStringSet(code - 1, out);
  }
}

class TokenMapChunkReader {
  constructor(data, tokenCount, pages, cacheSize) {
    this.data = data;
    this.tokenCount = tokenCount;
    this.pages = pages;
    this.cacheSize = cacheSize;
    this.cache = new Map();
  }

  static unpack(bytes, offset, size, cacheSize) {
    const reader = new BytesReader(bytes, offset, size);
    const tokenCount = reader.readMbUInt();
    const tokenPageCount = reader.readMbUInt();
    const pages = [];
    let tokenBase = 0;
    let previousTokenByteSize = -1;

    for (let pageIndex = 0; pageIndex < tokenPageCount; pageIndex += 1) {
      const pageHeader = reader.readByte();
      if (pageHeader !== 0) {
        throw new Error("unsupported TM00 PageHeader");
      }
      const tokenByteSize = reader.readMbUInt();
      const pageTokenCount = reader.readMbUInt();
      const tokenStreamSize = reader.readMbUInt();
      if (tokenByteSize < previousTokenByteSize) {
        throw new Error("TM00 token pages must be sorted by token_byte_size");
      }
      previousTokenByteSize = tokenByteSize;
      if (tokenByteSize === 0) {
        throw new Error("TM00 token_byte_size must be positive");
      }
      if (pageTokenCount === 0) {
        throw new Error("TM00 page_token_count must be positive");
      }
      if (tokenStreamSize !== tokenByteSize * pageTokenCount) {
        throw new Error("TM00 token stream size mismatch");
      }
      pages.push({
        tokenBase,
        tokenByteSize,
        pageTokenCount,
        tokenStreamStart: reader.pos,
        tokenStreamSize,
      });
      reader.skipInByte(tokenStreamSize);
      tokenBase += pageTokenCount;
    }

    if (tokenBase !== tokenCount) {
      throw new Error("TM00 token count mismatch");
    }
    if (reader.pos !== offset + size) {
      throw new Error("TM00 has trailing bytes");
    }
    return new TokenMapChunkReader(bytes, tokenCount, pages, cacheSize);
  }

  get(tokenId) {
    if (!Number.isInteger(tokenId) || tokenId < 0 || tokenId >= this.tokenCount) {
      throw new RangeError("TM00 token id out of range");
    }
    const cached = this.cache.get(tokenId);
    if (cached !== undefined) {
      this.cache.delete(tokenId);
      this.cache.set(tokenId, cached);
      return cached;
    }

    const page = this.findPage(tokenId);
    const indexInPage = tokenId - page.tokenBase;
    const start = page.tokenStreamStart + indexInPage * page.tokenByteSize;
    const end = start + page.tokenByteSize;
    if (end > page.tokenStreamStart + page.tokenStreamSize) {
      throw new Error("TM00 token stream truncated");
    }
    const token = this.data.subarray(start, end);
    if (this.cacheSize > 0) {
      this.cache.set(tokenId, token);
      while (this.cache.size > this.cacheSize) {
        this.cache.delete(this.cache.keys().next().value);
      }
    }
    return token;
  }

  findPage(tokenId) {
    for (const page of this.pages) {
      if (tokenId < page.tokenBase + page.pageTokenCount) {
        return page;
      }
    }
    throw new RangeError("TM00 token id out of range");
  }
}

class TextTableChunkReader {
  constructor(recordCount, pageSize, pageCount, tokenBits, pages) {
    this.recordCount = recordCount;
    this.pageSize = pageSize;
    this.pageCount = pageCount;
    this.tokenBits = tokenBits;
    this.pages = pages;
  }

  static unpack(bytes, offset, size) {
    const reader = new BytesReader(bytes, offset, size);
    const recordCount = reader.readMbUInt();
    const pageSize = reader.readMbUInt();
    const pageCount = reader.readMbUInt();
    const tokenBits = reader.readMbUInt();
    if (tokenBits < 1 || tokenBits > 16) {
      throw new Error("invalid TT00 token_bits");
    }

    const pages = [];
    let previousTokenCount = -1;
    let countedRecords = 0;
    for (let pageIndex = 0; pageIndex < pageCount; pageIndex += 1) {
      const page = readMappedTextTablePage(reader);
      if (page.recordTokenCount < previousTokenCount) {
        throw new Error("TT00 pages must be sorted by record_token_count");
      }
      previousTokenCount = page.recordTokenCount;
      countedRecords += page.pageRecordCount;
      pages.push(page);
    }

    if (reader.pos !== offset + size) {
      throw new Error("TT00 has trailing bytes");
    }
    if (countedRecords !== recordCount) {
      throw new Error("TT00 record count mismatch");
    }

    return new TextTableChunkReader(recordCount, pageSize, pageCount, tokenBits, pages);
  }
}

class HierarchicalIndexChunkReader {
  constructor(data, maxDepth, recordCount, codeBits, rootCount, indexStreamStart, indexStreamSize) {
    this.data = data;
    this.maxDepth = maxDepth;
    this.recordCount = recordCount;
    this.codeBits = codeBits;
    this.rootCount = rootCount;
    this.indexStreamStart = indexStreamStart;
    this.indexStreamSize = indexStreamSize;
  }

  static unpack(bytes, offset, size) {
    const reader = new BytesReader(bytes, offset, size);
    const maxDepth = reader.readMbUInt();
    const recordCount = reader.readMbUInt();
    const codeBits = reader.readMbUInt();
    const rootCount = reader.readMbUInt();
    const streamSize = reader.readMbUInt();
    const streamStart = reader.pos;
    reader.skipInByte(streamSize);
    if (reader.pos !== offset + size) {
      throw new Error("TI00 has trailing bytes");
    }
    validateHierarchicalIndexHeader(maxDepth, recordCount, codeBits, rootCount, streamSize);
    return new HierarchicalIndexChunkReader(
      bytes,
      maxDepth,
      recordCount,
      codeBits,
      rootCount,
      streamStart,
      streamSize,
    );
  }

  readCodeSet(index, out = null) {
    if (!Number.isInteger(index) || index < 0 || index >= this.recordCount) {
      throw new RangeError("TI00 index out of range");
    }

    const result = out ?? new Array(this.maxDepth);
    while (result.length < this.maxDepth) {
      result.push(0);
    }
    result.length = this.maxDepth;

    const reader = new BytesReader(this.data, this.indexStreamStart, this.indexStreamSize);
    if (this.maxDepth === 1) {
      this.readLeafBlocksByCount(reader, this.rootCount, index, result);
    } else {
      this.readPrefixesByCount(reader, 0, this.rootCount, index, result);
    }
    return result;
  }

  readPrefixesByCount(reader, depth, prefixCount, target, out) {
    for (let prefixIndex = 0; prefixIndex < prefixCount; prefixIndex += 1) {
      const code = reader.readBitsAsInt32(this.codeBits);
      const leafCount = reader.readMbUInt();
      const payloadBits = reader.readMbUInt();
      if (target < leafCount) {
        out[depth] = code;
        this.readChildrenByLeafCount(reader, depth + 1, leafCount, target, out);
        return;
      }
      this.skipPayload(reader, depth + 1, leafCount, payloadBits);
      target -= leafCount;
    }
    throw new RangeError("TI00 index not found");
  }

  readChildrenByLeafCount(reader, depth, leafCount, target, out) {
    if (depth === this.maxDepth - 1) {
      this.readLeafBlocksByLeafCount(reader, leafCount, target, out);
      return;
    }

    let consumed = 0;
    while (consumed < leafCount) {
      const code = reader.readBitsAsInt32(this.codeBits);
      const childLeafCount = reader.readMbUInt();
      const payloadBits = reader.readMbUInt();
      if (target < consumed + childLeafCount) {
        out[depth] = code;
        this.readChildrenByLeafCount(
          reader,
          depth + 1,
          childLeafCount,
          target - consumed,
          out,
        );
        return;
      }
      this.skipPayload(reader, depth + 1, childLeafCount, payloadBits);
      consumed += childLeafCount;
    }
    throw new RangeError("TI00 child index not found");
  }

  readLeafBlocksByCount(reader, blockCount, target, out) {
    for (let blockIndex = 0; blockIndex < blockCount; blockIndex += 1) {
      const leafCount = reader.readMbUInt();
      if (target < leafCount) {
        reader.skipBits(target * this.codeBits);
        out[this.maxDepth - 1] = reader.readBitsAsInt32(this.codeBits);
        return;
      }
      reader.skipBits(leafCount * this.codeBits);
      target -= leafCount;
    }
    throw new RangeError("TI00 leaf index not found");
  }

  readLeafBlocksByLeafCount(reader, leafCount, target, out) {
    let consumed = 0;
    while (consumed < leafCount) {
      const blockLeafCount = reader.readMbUInt();
      if (target < consumed + blockLeafCount) {
        reader.skipBits((target - consumed) * this.codeBits);
        out[this.maxDepth - 1] = reader.readBitsAsInt32(this.codeBits);
        return;
      }
      reader.skipBits(blockLeafCount * this.codeBits);
      consumed += blockLeafCount;
    }
    throw new RangeError("TI00 leaf index not found");
  }

  skipPayload(reader, depth, leafCount, payloadBits) {
    if (payloadBits > 0) {
      reader.skipBits(payloadBits);
      return;
    }
    this.skipChildrenByLeafCount(reader, depth, leafCount);
  }

  skipChildrenByLeafCount(reader, depth, leafCount) {
    let consumed = 0;
    if (depth === this.maxDepth - 1) {
      while (consumed < leafCount) {
        const blockLeafCount = reader.readMbUInt();
        reader.skipBits(blockLeafCount * this.codeBits);
        consumed += blockLeafCount;
      }
      return;
    }

    while (consumed < leafCount) {
      reader.readBitsAsInt32(this.codeBits);
      const childLeafCount = reader.readMbUInt();
      const payloadBits = reader.readMbUInt();
      this.skipPayload(reader, depth + 1, childLeafCount, payloadBits);
      consumed += childLeafCount;
    }
  }
}

function readMappedChunk(reader, sourceSize) {
  const name = readAscii(reader, 4);
  const size = reader.readMbUInt();
  const dataStart = reader.pos;
  if (dataStart + size > sourceSize) {
    throw new Error("chunk data exceeds source size");
  }
  reader.skipInByte(size);
  return { name, dataStart, size };
}

function parseGisWordBookHeader(bytes, offset, size) {
  const reader = new BytesReader(bytes, offset, size);
  const version = readBStrAscii(reader, 16);
  if (version !== GISWORDBOOK_VERSION) {
    throw new Error(`invalid GisWordBook version: ${version}`);
  }
  const metadataSize = reader.readMbUInt();
  const metadata = metadataSize === 0 ? null : textDecoder.decode(reader.readAsBytes(metadataSize));
  if (reader.pos !== offset + size) {
    throw new Error("GW00 has trailing bytes");
  }
  return { version, metadata };
}

function readMappedTextTablePage(reader) {
  const pageHeader = reader.readByte();
  if (pageHeader !== 0) {
    throw new Error("unsupported TT00 PageHeader");
  }
  const recordTokenCount = reader.readMbUInt();
  const pageRecordCount = reader.readMbUInt();
  const recordStreamSize = reader.readMbUInt();
  const recordStreamStart = reader.pos;
  reader.skipInByte(recordStreamSize);
  return {
    recordTokenCount,
    pageRecordCount,
    recordStreamStart,
    recordStreamSize,
    pageHeader,
  };
}

function decodeMappedPageRecordWithTokenGetter(bytes, page, indexInPage, tokenBits, tokenGetter) {
  if (!Number.isInteger(indexInPage) || indexInPage < 0 || indexInPage >= page.pageRecordCount) {
    throw new RangeError("TT00 page record index out of range");
  }

  const reader = new BytesReader(bytes, page.recordStreamStart, page.recordStreamSize);
  const packetCount = reader.readMbUInt();
  const palette = new Array(PALETTE_SIZE + 1).fill(null);
  const chunks = [];
  let byteLength = 0;
  let recordIndex = 0;

  for (let packetIndex = 0; packetIndex < packetCount; packetIndex += 1) {
    const packetType = reader.readBitsAsInt32(2);
    const valueBitSize = reader.readMbUInt();
    if (packetType === 0) {
      const startBitPosition = bitPosition(reader);
      const entrySlots = reader.readBitsAsInt32(15);
      palette.fill(null);
      for (let bitIndex = 0; bitIndex < PALETTE_SIZE; bitIndex += 1) {
        if ((entrySlots & (1 << bitIndex)) !== 0) {
          palette[bitIndex + 1] = reader.readBitsAsInt32(tokenBits);
        }
      }
      assertConsumedBits(reader, startBitPosition, valueBitSize);
      continue;
    }

    if (packetType === 1) {
      const startBitPosition = bitPosition(reader);
      const slot = reader.readBitsAsInt32(4);
      if (slot === 0) {
        throw new Error("TT00 UpdatePalettePacket slot must be non-zero");
      }
      palette[slot] = reader.readBitsAsInt32(tokenBits);
      assertConsumedBits(reader, startBitPosition, valueBitSize);
      continue;
    }

    if (packetType === 2) {
      if (valueBitSize % 4 !== 0) {
        throw new Error("TT00 TokenPayloadPacket bit size must be multiple of 4");
      }
      const localCodeCount = valueBitSize / 4;
      for (let localCodeIndex = 0; localCodeIndex < localCodeCount; localCodeIndex += 1) {
        const localCode = reader.readBitsAsInt32(4);
        if (localCode === 0) {
          if (recordIndex === indexInPage) {
            return concatBytes(chunks, byteLength);
          }
          recordIndex += 1;
          chunks.length = 0;
          byteLength = 0;
        } else if (recordIndex === indexInPage) {
          const tokenId = palette[localCode];
          if (tokenId === null) {
            throw new Error("TT00 token payload references empty palette slot");
          }
          const token = tokenGetter(tokenId);
          chunks.push(token);
          byteLength += token.length;
        }
      }
      continue;
    }

    reader.skipBits(valueBitSize);
  }

  throw new Error("TT00 target record terminator not found");
}

function validateHierarchicalIndexHeader(maxDepth, recordCount, codeBits, rootCount, streamSize) {
  if (maxDepth <= 0) {
    throw new Error("TI00 max_depth must be positive");
  }
  if (recordCount <= 0) {
    throw new Error("TI00 record_count must be positive");
  }
  if (codeBits < 1 || codeBits > 31) {
    throw new Error("TI00 code_bits must be in 1..31");
  }
  if (rootCount <= 0) {
    throw new Error("TI00 root_count must be positive");
  }
  if (streamSize <= 0) {
    throw new Error("TI00 IndexStream must not be empty");
  }
}

function requiredBits(count) {
  if (count <= 1) {
    return 1;
  }
  return Math.ceil(Math.log2(count));
}

function readAscii(reader, length) {
  const bytes = reader.readAsBytes(length);
  let text = "";
  for (const byte of bytes) {
    text += String.fromCharCode(byte);
  }
  return text;
}

function readBStrAscii(reader, length) {
  const bytes = reader.readAsBytes(length);
  let textLength = bytes.indexOf(0);
  if (textLength < 0) {
    textLength = bytes.length;
  }
  let text = "";
  for (let byteIndex = 0; byteIndex < textLength; byteIndex += 1) {
    text += String.fromCharCode(bytes[byteIndex]);
  }
  return text;
}

function bitPosition(reader) {
  return reader.pos * 8 - reader.getBitOffset();
}

function assertConsumedBits(reader, startBitPosition, expectedBits) {
  const consumed = bitPosition(reader) - startBitPosition;
  if (consumed !== expectedBits) {
    throw new Error(`TT00 packet size mismatch: ${consumed} != ${expectedBits}`);
  }
}

function concatBytes(chunks, byteLength) {
  if (chunks.length === 1) {
    return chunks[0];
  }
  const result = new Uint8Array(byteLength);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }
  return result;
}
