const MUINT5_BASE = 16843260;
const UINT32_MAX = 0xffffffff;

export class LzssByteReader {
  constructor(sourceReader, windowSize = 256) {
    this.source = sourceReader;
    this.window = new Array(windowSize).fill(0);
    this.ptr = 0;
    this.state = 0;
    this.limit = 0;
    this.index = 0;
    this.refOffset = 0;
  }

  readByte() {
    while (true) {
      if (this.state === 0) {
        const flag = this.source.readBitsAsInt32(1);
        this.state = flag === 0 ? 10 : 20;
      }
      if (this.state === 10) {
        this.limit = this.source.readBitsAsInt32(4) + 1;
        this.index = 0;
        this.state = 11;
      }
      if (this.state === 11) {
        const value = this.source.readByte();
        this._push(value);
        this.index++;
        if (this.index >= this.limit) {
          this.state = 0;
        }
        return value;
      }
      if (this.state === 20) {
        this.refOffset = this.source.readByte();
        this.index = 0;
        this.limit = this.source.readBitsAsInt32(4) + 2;
        this.state = 21;
      }
      if (this.state === 21) {
        const value = this._get(this.refOffset);
        this._push(value);
        this.index++;
        if (this.index >= this.limit) {
          this.state = 0;
        }
        return value;
      }
    }
  }

  _get(index) {
    return this.window[(this.ptr + index) % this.window.length];
  }

  _push(value) {
    this.window[this.ptr] = value & 0xff;
    this.ptr = (this.ptr + 1) % this.window.length;
  }
}

export class IteratorByteReader {
  constructor(byteReader) {
    this.byteReader = byteReader;
    this.bitLeft = 0;
    this.bitCache = 0;
  }

  readBitsAsInt32(bits) {
    if (bits < 0 || bits > 31) {
      throw new RangeError("bits must be in 0..31");
    }
    if (bits === 0) {
      return 0;
    }
    let result = 0;
    let left = this.bitLeft;
    let cache = this.bitCache;
    let remaining = bits;
    if (left > 0) {
      const readBits = Math.min(left, remaining);
      result = (cache >> (left - readBits)) & ((1 << readBits) - 1);
      left -= readBits;
      remaining -= readBits;
      cache = left > 0 ? cache & ((1 << left) - 1) : 0;
    }
    while (remaining >= 8) {
      result = (result << 8) | this.byteReader.readByte();
      remaining -= 8;
    }
    if (remaining > 0) {
      const nextByte = this.byteReader.readByte();
      result = (result << remaining) | (nextByte >> (8 - remaining));
      left = 8 - remaining;
      cache = nextByte & ((1 << left) - 1);
    }
    this.bitLeft = left;
    this.bitCache = cache;
    return result;
  }

  readByte() {
    const left = this.bitLeft;
    const nextByte = this.byteReader.readByte();
    if (left === 0) {
      return nextByte;
    }
    const merged = (this.bitCache << 8) | nextByte;
    const result = (merged >> left) & 0xff;
    this.bitCache = merged & ((1 << left) - 1);
    return result;
  }

  readMbUInt() {
    const prefix = this.readByte();
    if (prefix < 252) return prefix;
    if (prefix === 255) return 252 + this.readByte();
    if (prefix === 254) return 508 + (this.readByte() << 8) + this.readByte();
    if (prefix === 253) return 66044 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    if (prefix === 252) {
      const value = this.readByte() * 0x1000000 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
      if (value > UINT32_MAX - MUINT5_BASE) {
        throw new RangeError("MBUInt exceeds Uint32 range");
      }
      return MUINT5_BASE + value;
    }
    throw new Error("invalid MBUInt prefix");
  }

  readMbInt() {
    const head = this.readByte();
    const sign = (head & 0x80) !== 0 ? -1 : 1;
    const prefix = head & 0x7f;
    let value;
    if (prefix < 124) value = prefix;
    else if (prefix === 127) value = 124 + this.readByte();
    else if (prefix === 126) value = 380 + (this.readByte() << 8) + this.readByte();
    else if (prefix === 125) value = 65916 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    else if (prefix === 124) value = 16843132 + this.readByte() * 0x1000000 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    else throw new Error("invalid MBInt prefix");
    return sign * value;
  }

  skipToByte() {
    const skipped = this.bitLeft;
    this.bitLeft = 0;
    this.bitCache = 0;
    return skipped;
  }
}
