import { BytesReader } from "../../io/BytesReader.js";
import { RawRaster } from "../../raster/RawRaster.js";
import { GaluchatImageDataChunk01Reader } from "../../chunk/gi01/GaluchatImageDataChunk01Reader.js";
import { WGSMapHeader } from "./WGSMapHeader.js";

export class GaluchatWGSMap3Reader {
  constructor(header, reader) {
    this.header = header;
    this.reader = reader;
  }

  static fromUint8Array(bytes) {
    return GaluchatWGSMap3Reader.unpack(bytes);
  }

  static unpack(bytes) {
    const reader = new BytesReader(bytes);
    const header = WGSMapHeader.unpack(reader);
    const chunkReader = new GaluchatImageDataChunk01Reader(bytes, reader.pos);
    return new GaluchatWGSMap3Reader(header, chunkReader);
  }

  get unitInvX() {
    return this.header.unitInvX;
  }

  get unitInvY() {
    return this.header.unitInvY;
  }

  get area() {
    return {
      x: this.header.west,
      y: this.header.south,
      width: this.reader.width,
      height: this.reader.height,
    };
  }

  get areaOfWgs() {
    const area = this.area;
    return {
      x: area.x / this.header.unitInvX,
      y: area.y / this.header.unitInvY,
      width: area.width / this.header.unitInvX,
      height: area.height / this.header.unitInvY,
    };
  }

  readPoint(x, y) {
    if (!this.reader.isInside(x, y)) {
      return null;
    }
    return this.reader.readPoint(x, y);
  }

  readWgsPoint(ix, iy) {
    return this.readPoint(ix - this.header.west, iy - this.header.south);
  }

  readWgsPointf(lon, lat) {
    return this.readWgsPoint(
      Math.round(lon * this.header.unitInvX),
      Math.round(lat * this.header.unitInvY),
    );
  }

  readRect(x, y, width, height) {
    const raster = RawRaster.createRaster(width, height);
    return this.reader.readRect(x, y, raster);
  }

  readWgsRect(rect) {
    const raster = RawRaster.createRaster(rect.width, rect.height);
    return this.reader.readRect(rect.x - this.header.west, rect.y - this.header.south, raster);
  }

  readWgsRectf(rect) {
    return this.readWgsRect({
      x: Math.round(rect.x * this.header.unitInvX),
      y: Math.round(rect.y * this.header.unitInvY),
      width: Math.round(rect.width * this.header.unitInvX),
      height: Math.round(rect.height * this.header.unitInvY),
    });
  }

  toRaster() {
    const raster = RawRaster.createRaster(this.reader.width, this.reader.height);
    return this.reader.readRect(0, 0, raster);
  }
}
